//! Bearer token authentication middleware for the web gateway.use axum::{    extract::{Request, State},    http::{HeaderMap, Method, StatusCode},    middleware::Next,    response::{IntoResponse, Response},};use subtle::ConstantTimeEq;/// Shared auth state injected via axum middleware state.#[derive(Clone)]pub struct AuthState {    pub token: String,}/// Whether query-string token auth is allowed for this request.////// Only GET requests to streaming endpoints may use `?token=xxx`. This/// minimizes token-in-URL exposure on state-changing routes, where the token/// would leak via server logs, Referer headers, and browser history.////// Allowed endpoints:/// - SSE: `/api/chat/events`, `/api/logs/events` (EventSource can't set headers)/// - WebSocket: `/api/chat/ws` (WS upgrade can't set custom headers)////// If you add a new SSE or WebSocket endpoint, add its path here.fn allows_query_token_auth(request: &Request) -> bool {    if request.method() != Method::GET {        return false;    }    matches!(        request.uri().path(),        "/api/chat/events" | "/api/logs/events" | "/api/chat/ws"    )}/// Extract the `token` query parameter value, URL-decoded.fn query_token(request: &Request) -> Option<String> {    let query = request.uri().query()?;    url::form_urlencoded::parse(query.as_bytes()).find_map(|(k, v)| {        if k == "token" {            Some(v.into_owned())        } else {            None        }    })}/// Auth middleware that validates bearer token from header or query param.////// SSE connections can't set headers from `EventSource`, so we also accept/// `?token=xxx` as a query parameter, but only on SSE endpoints.